    'st.grp.office': 'Office',
    'st.grp.slipShared': 'Receipt Language & Type Size (both systems)',
    'st.grp.slipShared.desc': 'These apply to every printed receipt, voucher and bill — water supply and donor alike. The committee prints both on the same paper, so there is one setting rather than two to keep in sync. What differs per system is on that system\u2019s own tab: Water Supply \u2192 Bills & Water Documents, and Donors & Projects \u2192 Receipts & Donor Documents.',
    'st.grp.waterPrinter': 'Water Supply — Printer & Paper',
    'st.grp.waterPrinter.desc': 'Controls the slip a water supply consumer is handed. The donor equivalent lives under Donors & Projects \u2192 Receipts & Donor Documents.',
    'st.grp.donorPrinter': 'Donor Receipts — Printer & Paper',
    'st.grp.donorPrinter.desc': 'Controls the slip a donor is handed. The water supply equivalent lives under Water Supply \u2192 Bills & Water Documents.',
    'st.grp.invoiceFooter': 'Water Supply Receipt — Wording, Help Numbers & Links',
    'st.grp.invoiceFooter.desc': 'Every word and number printed on a WATER SUPPLY bill, receipt and payment voucher. Donor receipts have their own copy of all of this under Donors & Projects \u2192 Receipts & Donor Documents; changing it here does not touch them.',
    'st.grp.donorInvoiceFooter': 'Donor Receipt — Wording, Help Numbers & Links',
    'st.grp.donorInvoiceFooter.desc': 'Every word and number printed on a DONOR receipt. Numbers and links left blank here fall back to the water supply values, but the three prose fields (instructions, fund note, helpline/complaint wording) never do — blank means nothing prints, so that water supply wording can never appear on a donation receipt.',
