    'st.accountingReset': 'accounting reset',
    'st.welfareResetLabel': 'Welfare & Projects Test Data',
    'st.welfareResetBlurb': 'Clears everything the reset above doesn\'t: projects (and their comments, votes, media), Kafalat children, Wazifa students, Esal-e-Sawab objects, Zakat rounds, the needs register, and shared-pool pledges — plus donors, vouchers, and ledger entries via the same accounting reset. The 3 pool definitions, chart of accounts, portal user logins, and everything else stay exactly as they are. This cannot be undone.',
    'st.welfareResetDone': 'Welfare & projects test data cleared.',
    'st.opsResetLabel': 'Operational & Engagement Data',
    'st.opsResetBlurb': 'Clears everything the two resets above don\'t: Meetings & Agenda (and the achievements the public site shows), reminders, employees, suggestions, complaints, the news ticker, appeals, notifications, blood donors, job listings, monthly closing reports, and the audit log. Inventory is trimmed to a single example item rather than deleted outright. Config that isn\'t a record of a specific event — complaint handlers, notification channel settings, employee roles — stays exactly as it is. This cannot be undone.',
    'st.opsResetDone': 'Operational & engagement data cleared.',
