    'wz.guide.toggle': 'How this works',
    'wz.guide.applications.title': 'Applications tab',
    'wz.guide.applications.body': 'A student applies, the committee scores merit and need against the written formula in Settings, then decides — a grant that never needs repaying, or a qarz-e-hasana loan the student repays once employed, at whatever monthly amount the committee sets once that happens.',
