    'wz.guide.awards.body': 'Every approved student, their instalments due against the school directly, and — where the family agreed to pay something themselves — their own contribution recorded here too.',
    'wz.guide.loans.title': 'Loans, repayment, and write-off',
    'wz.guide.loans.body': 'A loan sits untouched until the student tells the committee they are employed — repayment is never advertised or shown on the application, and never starts on its own. Once marked employed, one instalment a month is raised automatically at whatever amount the committee fixed, continuing until the balance reaches zero. The committee can waive the remainder outright at any time, entirely at its own discretion — that decision is never shown to the student in advance or promised on any form.',
    'wz.guide.collections.title': 'Collections tab',
    'wz.guide.collections.body': 'Pledges toward the shared Wazifa pool wait here for confirmation against the slip or cash received, plus lapsed donors and any month the committee had to cover from its own funds — the same pattern as Kafalat and Sadqa\'s own Collections tabs.',
