    'pwz.s.qarz': 'Qarz-e-Hasana — will you return it?',
    'pwz.qarzUrdu': 'یہ وظیفہ عام طور پر بلا سود قرضِ حسنہ کی صورت میں دیا جاتا ہے، تاکہ واپس آنے والی رقم سے اگلے طالب علم کی تعلیم ہو سکے۔ کیا یہ آپ کے خاندان پر لاگو ہوگا، یہ کمیٹی آپ کی درخواست دیکھ کر طے کرے گی۔',
    'pwz.qarzEnglish': "Most awards are structured as an interest-free qarz-e-hasana, so what comes back educates the next student. Whether that applies to your family is the committee's own finding, decided from your application — not a choice made here.",
    'pwz.f.repaymentPledge': 'Yes — I intend to return it once I am earning',
    'pwz.f.repaymentHelp': 'Interest-free. No date is fixed now; the committee agrees one with you after you start work.',
    'pwz.f.repaymentNoPressure': 'A qarz-e-hasana is a real obligation, not a formality — but it is also what lets this fund reach the next student. Choose honestly; the committee would rather know now than chase you later.',
    'pwz.f.repaymentNote': 'Anything you want to say about it',
