    'zc.tab.ushr': 'Ushr',
    'zc.zakatHelp': 'Enter what you have held for a full lunar year, and what you owe. Zakat is 2.5% of the balance if it is above the nisab.',
    'zc.ushrHelp': 'Ushr is due on the harvest, at the time of harvest — not once a year like zakat.',
