    'pwz.s.business': 'Family business or joint income',
    'pwz.businessUrdu': 'اگر گھر والے مل کر کوئی کاروبار، دکان، ٹریکٹر، مال مویشی یا زمین چلاتے ہیں تو وہ یہاں لکھیں اور بتائیں کہ آپ کے گھرانے کا ماہانہ حصہ کتنا بنتا ہے۔',
    'pwz.businessEnglish': 'Families here often run one shop, one tractor or one herd between several brothers. Asking each man his "salary" gets zero from all of them and misses the household’s real income.',
