    'pwz.s.share': 'Monthly cost, and how repayment works',
    'pwz.shareUrdu': 'آپ کے ادارے کی ماہانہ فیس اور آمد و رفت کا خرچ کتنا ہے؟ کمیٹی یہ پوری رقم ہر ماہ براہِ راست ادارے یا آپ کو ادا کرے گی — تعلیم کے دوران آپ سے کچھ نہیں مانگا جائے گا۔ آپ کی تعلیم جاری رہنے اور سنجیدگی کی تصدیق کمیٹی ہر ماہ فون پر کرے گی۔ رقم کی واپسی صرف اس وقت شروع ہو گی جب آپ کی تعلیم مکمل ہو جائے گی، اسی رقم اور شیڈول کے مطابق جو آپ کے معاہدے میں طے پائے گا۔',
    'pwz.shareEnglish': 'The committee pays this in full, every month, directly to the institution or to you — nothing is asked of you while you study. Your seriousness is confirmed with a monthly phone call, not a monthly payment. Paying it back only begins once your education is complete, at the amount and schedule fixed in your agreement.',
