    'kf.guide.toggle': 'How this works',
    'kf.guide.sponsorOrShare.title': 'How a child gets sponsored',
    'kf.guide.sponsorOrShare.body': 'A donor either names one child from the portal (Sponsor a Child) or joins the shared pool with no name attached — both are the same action underneath, and both count toward the same child. There is nothing to set up here for that to work; it runs from the donor portal on its own.',
    'kf.guide.measuring.title': 'The measuring account',
    'kf.guide.measuring.body': 'Not a bank account — a running tally of what this year\'s active children need (Required) against what has actually been confirmed (Confirmed). Approving a child adds their year\'s package to Required automatically; a confirmed donation, named or shared, reduces it. Outstanding is the gap donors still need to close, and Monthly Target is that gap spread over the months left in the school year.',
    'kf.guide.collections.title': 'Collections tab',
    'kf.guide.collections.body': 'Everything about donors, not children. Pledges a donor has announced from the portal wait here for you to confirm against the slip they attach (or cash actually received) — tap Confirm and it becomes a real donation with its own voucher, or Decline if it never arrives. Below that: donors who stopped paying and their phone number (call them — it is almost always someone who forgot, not someone who quit), and any month the pool fell short, which only the committee can decide to cover from unrestricted funds.',
    'kf.guide.operations.title': 'Operations tab',
    'kf.guide.operations.body': 'The two categories that run on their own schedule: a uniform twice a year, transport and pocket money every month, both generated automatically once a child is approved. Pay marks it settled and posts the voucher; Skip records that it was deliberately not paid this cycle (a child on leave, say) without breaking next month\'s schedule.',
    'kf.guide.fees.title': 'Fees section',
    'kf.guide.fees.body': 'School fee, books, medical, exam fee and tuition — budgeted per child but paid as the school actually bills, often per term, so a line can be paid more than once across the year. Each payment wants who it was paid to, who signed for it, and the slip photo — that photo is the actual paper trail behind the number, and the point of keeping it here rather than in a drawer.',
    'kf.guide.reverify.title': 'Annual re-verification',
    'kf.guide.reverify.body': 'Once a year, someone visits the family again and answers the same questions as the first visit — has anyone\'s income changed, is the child still enrolled. Two names on the form, not one; a decision this size should never rest on a single person\'s word.',
    'kf.guide.record.title': 'The printable record',
    'kf.guide.record.body': 'Every child has one button — the receipt icon on their card — that produces a single printable page: every rupee spent on them this year, what it bought, who signed for it, and a total, with space at the bottom for the committee\'s own signature. That is the hard copy for the file, independent of anything on this screen.',

