    'mb.role.rider.title': 'Riders & customers', 'mb.role.rider.step1': 'Pick a destination — adda van, shared seats, rides home and private cars are compared side by side.',
    'mb.role.rider.step2': 'Adda and shared seats have fixed fares and confirm instantly. Cars, weddings, loads and machinery go out as a request.',
    'mb.role.rider.step3': 'The driver or owner sends a price. Accept it, or send one counter offer.',
    'mb.role.rider.step4': 'No advance for machinery, tractor or loader bookings. Wedding vehicles take a 30% advance, paid by JazzCash or Easypaisa to the committee.',
    'mb.role.rider.step5': 'Follow the status, pay the rest after the job, then rate the driver.',
    'mb.role.driver.title': 'Drivers', 'mb.role.driver.step1': 'Get your CNIC, licence and vehicle papers verified by the committee.',
    'mb.role.driver.step2': 'Go online. Adda vans join the queue at the stand, first in, first out.',
    'mb.role.driver.step3': 'For each request, accept the estimate, send your own price, or decline.',
    'mb.role.driver.step4': 'Tap Start and Complete. The committee keeps its commission; the rest is yours, paid to JazzCash every Friday.',
    'mb.role.owner.title': 'Machinery owners', 'mb.role.owner.step1': 'The committee lists each machine with an hourly rate, minimum hours and a delivery charge.',
    'mb.role.owner.step2': 'Requests arrive with the site, date and hours. You accept, decline, or send your own price.',
