    'mb.role.rider.step3': 'ڈرائیور یا مالک قیمت بھیجتا ہے۔ آپ منظور کریں یا ایک بار جوابی پیشکش دیں۔',
    'mb.role.rider.step4': 'مشینری، ٹریکٹر یا لوڈر کی بکنگ پر کوئی ایڈوانس نہیں۔ شادی کی گاڑیوں پر 30% ایڈوانس کمیٹی کو جاز کیش / ایزی پیسہ سے جاتا ہے۔',
