    'mb.role.driver.step2': 'ایپ میں آن لائن ہوں۔ اڈہ وین والے قطار میں شامل ہوتے ہیں — پہلے آئیں، پہلے جائیں۔',
    'mb.role.driver.step3': 'نئی درخواست پر تخمینی قیمت منظور کریں، اپنی قیمت بھیجیں یا انکار کریں۔',
    'mb.role.driver.step4': 'شروع اور مکمل پر کلک کریں۔ کمیٹی اپنا کمیشن رکھتی ہے، باقی آپ کا ہے، ہر جمعہ جاز کیش میں۔',
